INSERT INTO `sys_config` VALUES (12, 'temp', '<!DOCTYPE html>\r\n<html>\r\n	<head>\r\n		<meta charset=\"utf-8\"/>\r\n		<title></title>\r\n		<style>\r\n			*{\r\n				margin: 0;\r\n				padding: 0;\r\n				box-sizing: border-box;\r\n			}\r\n			body{\r\n				font-family: SimSun;\r\n			}\r\n			section{\r\n				display:block;\r\n				margin: 20px 10px;\r\n			}\r\n			.title{\r\n				text-align: center;\r\n			}\r\n			.preface p{\r\n				line-height: 30px;\r\n			}\r\n			.preface p.content{\r\n				text-indent: 2em;\r\n			}\r\n			section > table{\r\n				table-layout: fixed;\r\n				width: 100%;\r\n				margin: 20px 0px;\r\n				text-align:center;\r\n				word-wrap:break-word;\r\n			}\r\n			section table td{\r\n				padding:5px 0px;\r\n			}\r\n		</style>\r\n	</head>\r\n	<body>\r\n		<img src=\"config/test.jpg\"/>\r\n		<!-- 标题 start -->\r\n		<section class=\"title\">\r\n			<h2>某报告</h2>\r\n		</section>\r\n		<!-- 标题 end -->\r\n		\r\n		<!-- 前言 start -->\r\n		<section class=\"preface\">\r\n			<p>尊敬的用户：</p>\r\n			<p class=\"content\">内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容内容</p>\r\n		</section>\r\n		<!-- 前言 end -->\r\n		\r\n		<!-- 汇总统计信息 start -->\r\n		<section class=\"count-info\">\r\n			<h4>汇总统计信息</h4>\r\n			<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n				<tr>\r\n					<td>本月笔数</td>\r\n					<td>近三个月数量对比</td>\r\n				</tr>\r\n				<tr>\r\n					<td>${curr}</td>\r\n					<td>\r\n						<table width=\"80%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" style=\"margin: 5px auto;\">\r\n							<tr>\r\n								<td>${one}</td>\r\n								<td>${two}</td>\r\n								<td>${three}</td>\r\n							</tr>\r\n						</table>\r\n					</td>\r\n				</tr>\r\n			</table>\r\n		</section>\r\n		<!-- 汇总统计信息 end -->\r\n		\r\n		<!-- 明细 start -->\r\n		<section class=\"detail\">\r\n			<h4>明细</h4>\r\n			<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n				<tr>\r\n					<td width=\"5%\">序号</td>\r\n					<td width=\"15%\">列1</td>\r\n					<td width=\"12%\">列2</td>\r\n					<td width=\"12%\">列3</td>\r\n					<td width=\"12%\">列4</td>\r\n					<td>列5</td>\r\n				</tr>\r\n				<#list detailList as ad>\r\n					<tr>\r\n						<td>${ad_index+1}</td>\r\n						<td>${ad.column1}</td>\r\n						<td>${ad.column2}</td>\r\n						<td>${ad.column3}</td>\r\n						<td>${ad.column4}</td>\r\n						<td>${ad.column5}</td>\r\n					</tr>\r\n				</#list>\r\n			</table>\r\n		</section>\r\n		<!-- 明细 end -->\r\n	</body>\r\n</html>\r\n', 1, NULL);
